package com.booksyde.controller;import com.booksyde.dto.response.ContractResponse;import com.booksyde.service.ContractService;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/contracts")public class ContractController{private final ContractService service;public ContractController(ContractService s){service=s;}@GetMapping("/me")public List<ContractResponse> mine(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt jwt){return service.mine(UUID.fromString(jwt.getSubject()));}@GetMapping @PreAuthorize("@authorizationService.hasRole(authentication, 'ADMIN')")public List<ContractResponse> all(){return service.all();}}
